mapper.select:
SELECT u.id, u.username, u.nickname, u.dept_id, u.phone, u.email, u.status, u.create_time, d.dept_name FROM sys_user u LEFT JOIN sys_dept d ON d.id = u.dept_id WHERE u.deleted = 0
AND u.username LIKE '%' || #{query.username} || '%'
AND u.status = #{query.status}
AND u.dept_id IN
#{deptId}
ORDER BY u.create_time DESC, u.id DESC
